select wmmd.*, wmm.id wmmId, wmm.serial_number wmmSN, wmm.applicant_name wmmfName, wmm.review_end_time review_time, wmm.reviewer_names wmmrName, wmm.create_time wmmcTime, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, mbf2.id mbfId2, mbf2.name mbfName2, ww2.id wwId2, ww2.name wwName2, mbf.id mbfId, mbf.name mbfName, ww.id wwId, ww.name wwName from wms_move_material_detail wmmd left join wms_move_material wmm on wmm.id = wmmd.move_material_id left join contract_project p on p.id = wmmd.project_id left join wms_workshop mbf on wmmd.source_workshop_id = mbf.id left join wms_warehouse ww on ww.id = wmmd.source_warehouse_id left join wms_workshop mbf2 on wmm.direction_workshop_id = mbf2.id left join wms_warehouse ww2 on ww2.id = wmm.direction_warehouse_id where wmmd.bool_delete_enum = 0 and wmm.review_status = 2
and wmmd.basic_class = #{basicClass}
and wmmd.bool_party_a = 1
and wmmd.bool_party_a = 0
and wmmd.material_is_whole = #{materialIsWhole}
and (wmmd.source_workshop_id = #{workshopId} or wmm.direction_workshop_id = #{workshopId})
AND wmmd.source_warehouse_id = #{warehouseId}
AND wmmd.project_Id = #{projectId}
AND wmmd.project_id in
#{projectId}
and wmm.review_end_time > #{outboundTime[0]}
and wmm.review_end_time < #{outboundTime[1]}
and wmm.serial_number like CONCAT('%', #{moveMaterialSN},'%')
and (wmm.applicant_name like CONCAT('%', #{operatorName},'%') or wmm.reviewer_names like CONCAT('%', #{operatorName},'%'))
and wmmd.classify_id in
#{item}
and wmmd.width = #{width}
and wmmd.length = #{length}
and wmmd.quantity >= #{minLength}
and wmmd.quantity <= #{maxLength}
and wmmd.theory_thickness = #{theoryThickness}
and wmmd.thickness = #{thickness}
and wmmd.color like CONCAT('%', #{color},'%')
and wmmd.specification like CONCAT('%', #{specification},'%')
and wmmd.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
AND wmmd.brand like CONCAT('%',#{brand},'%')
and wmmd.source_workshop_id in
#{item}

select
sum(wmmd.quantity) as quantityCount,
sum(wmmd.mete) as meteCount,
sum(wmmd.amount) as amountCount,
sum(wmmd.amount_excluding_VAT) as amountExcludingVatCount
from wms_move_material_detail wmmd
left join wms_move_material wmm on wmm.id = wmmd.move_material_id
left join contract_project p on p.id = wmmd.project_id
left join wms_workshop mbf on wmmd.source_workshop_id = mbf.id
left join wms_warehouse ww on ww.id = wmmd.source_warehouse_id
left join wms_workshop mbf2 on wmm.direction_workshop_id = mbf2.id
left join wms_warehouse ww2 on ww2.id = wmm.direction_warehouse_id
where
wmmd.bool_delete_enum = 0
and wmm.review_status = 2

    and wmmd.basic_class = #{basicClass}


    and wmmd.bool_party_a = 1


    and wmmd.bool_party_a = 0


    and wmmd.material_is_whole = #{materialIsWhole}


    and (wmmd.source_workshop_id = #{workshopId} or wmm.direction_workshop_id = #{workshopId})


    AND wmmd.source_warehouse_id = #{warehouseId}


    AND wmmd.project_Id = #{sourceProjectId}


    
        and wmm.review_end_time > #{outboundTime[0]}
    
    
        and wmm.review_end_time < #{outboundTime[1]}
    


    and wmm.serial_number like CONCAT('%', #{moveMaterialSN},'%')


    and (wmm.applicant_name like CONCAT('%', #{operatorName},'%')
    or wmm.reviewer_names like CONCAT('%', #{operatorName},'%'))


    and wmmd.classify_id in
    
        #{item}
    


    and wmmd.width = #{width}


    and wmmd.length = #{length}


    and wmmd.quantity >= #{minLength}


    and wmmd.quantity <= #{maxLength}


    and wmmd.theory_thickness = #{theoryThickness}


    and wmmd.thickness = #{thickness}


    and wmmd.color like CONCAT('%', #{color},'%')


    and wmmd.specification like CONCAT('%', #{specification},'%')


    and wmmd.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')


    AND wmmd.brand like CONCAT('%',#{brand},'%')


    and wmmd.source_workshop_id in
    
        #{item}

select wmmd.*, wc.name classifyName, wm.*, wmm.id wmmId, wmm.serial_number wmmSN, wmm.applicant_name applicantName, wmm.review_end_time review_time, wmm.create_time applicantTime, p.short_name projectName, p.serial_number projectNumber, p.name projectName, mbf2.name directionWmsWorkshopName, ww2.name directionWareHouseName, mbf.name wmsWorkshopName, ww.name warehouseName from wms_move_material_detail wmmd left join wms_move_material wmm on wmm.id = wmmd.move_material_id left join contract_project p on p.id = wmmd.project_id left join wms_workshop mbf on wmmd.source_workshop_id = mbf.id left join wms_warehouse ww on ww.id = wmmd.source_warehouse_id left join wms_workshop mbf2 on wmm.direction_workshop_id = mbf2.id left join wms_warehouse ww2 on ww2.id = wmm.direction_warehouse_id left join wms_classification wc on wmmd.classify_id = wc.id left join wms_measure wm on wm.classification_id = wmmd.classify_id where wmmd.bool_delete_enum = 0 and wmm.review_status = 2
